async function creerLivre(livre, signal) {
  const reponse = await fetch("/api/livres", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(livre),
    signal
  });

  if (!reponse.ok) {
    throw new Error(`Erreur HTTP ${reponse.status}`);
  }

  return reponse.json();
}
